import json,pathlib
# Curated teaching content: a distinct worked concept, exercise and project per ordered textbook topic.
R=[
('Variables','name binding|A variable name is a reference to an object.;assignment|= binds a name to an evaluated object.', 'Names are labels, not boxes containing values.|After y = x both names can reference the same object.|Rebinding x does not rewrite y.', 'x = 10\ny = x\nx = 20\nprint(x)\nprint(y)','20\n10','A name can be rebound without changing a different name.','Variable references','Maintain a student name, score and completion status.','Store a learner name and completed sessions in Study Intelligence.',True),
('Data types','type|Defines the operations supported by an object.;int|An integer value.;str|A sequence of Unicode characters.', 'Python has integer, float, string, Boolean, list and other types.|type() reports an object’s type.|Converting between types must be deliberate to prevent mistakes.', 'count = 4\nlabel = "study"\nprint(count)\nprint(label)','4\nstudy','"4" is a string, not an integer.','Value types','Display and validate a student profile with different data types.','Introduce a typed session duration and topic name.',True),
('Lists','list|An ordered mutable sequence.;index|An integer position starting at zero.', 'Square brackets create a list.|Indexing starts at 0; use an index to read one element.|append() mutates a list object, including through aliases.', 'topics = ["Python", "SQL"]\nalias = topics\ntopics.append("Pandas")\nprint(len(alias))','3','An alias observes mutation of the shared list.','Shared mutable collection','Create a study-session task list.','Store completed lessons in a list.',True),
('Tuples','tuple|An ordered, generally immutable sequence.;packing|Collecting multiple values into one tuple.', 'Use parentheses or comma-separated values to make tuples.|A tuple cannot have its elements reassigned.|Useful for fixed-size records, coordinates and return values.', 'position = (2, 3)\nprint(position[0])','2','The first position is 2; tuple entries cannot be assigned.', 'Fixed record','Represent a topic ID and title as a fixed record.','Store immutable session descriptors.',False),
('Sets','set|An unordered collection of distinct hashable elements.;membership|Testing whether a value belongs to a collection.', 'Repeated values collapse into one set member.|Sets support union, intersection and difference.|Iteration order must not be relied upon.', 'topics = {"Python", "SQL", "Python"}\nprint(len(topics))','2','Duplicate "Python" contributes only once.','Uniqueness','Deduplicate imported student subjects.','Deduplicate tags attached to study sessions.',False),
('Dictionaries','dict|A mapping from hashable keys to values.;key|A unique lookup identifier.', 'Braces associate a key with a value.|Lookups use dict[key] or dict.get(key).|Updates replace a value for one key.', 'student = {"name": "Derrick", "score": 90}\nprint(student["score"])','90','Dictionary lookup uses a key rather than a numeric position.','Key-value lookup','Build a student profile record.','Represent a study session with structured fields.',False),
('If / elif / else','condition|A Boolean expression evaluated to True or False.;branch|A code path taken when a condition is satisfied.', 'Python tests if first, then eligible elif branches, then else.|Indentation defines each branch body.|Only the first matching branch executes.', 'score = 75\nif score >= 80:\n    print("Excellent")\nelse:\n    print("Keep practising")','Keep practising','75 does not meet the >=80 condition.','Decision branches','Classify a completion rate as on-track or behind.','Add success warnings to session goals.',False),
('For loops','iteration|Processing items one at a time.;iterable|An object whose members can be visited.', 'for binds the loop variable to each item.|range(n) generates integer positions 0 through n-1.|Avoid mutating a list unintentionally during iteration.', 'for topic in ["Python", "SQL"]:\n    print(topic)','Python\nSQL','The loop body executes once for each item.','Sequence traversal','Display each assigned topic.','Calculate a progress report from sessions.',False),
('While loops','while|A loop repeated while its condition is True.;termination|An event that stops repetition.', 'while checks a condition before each iteration.|Update loop state to avoid infinite loops.|Use break deliberately when an exit condition appears.', 'attempts = 0\nwhile attempts < 3:\n    attempts += 1\nprint(attempts)','3','The counter increases until the condition is false.','Guarded repetition','Build a CLI menu loop.','Keep a study timer running until stopped.',False),
('Functions','function|A reusable callable block.;parameter|A name receiving input on invocation.;return|A result provided to the caller.', 'Define functions with def.|Parameters make one implementation reusable.|Use return to provide a value, rather than relying on print.', 'def percentage(completed, total):\n    return 100 * completed / total\nprint(percentage(7, 10))','70.0','The function returns a number computed from inputs.','Function call','Create a reusable grade calculator.','Extract a progress-percentage helper.',False),
('Lambda','lambda|A small anonymous function expression.;callable|An object that can be invoked.', 'lambda expressions contain exactly one expression.|Useful for a short sort key or transformation.|Named def functions are clearer for complex logic.', 'double = lambda x: x * 2\nprint(double(4))','8','An anonymous function computes 4×2.','One-expression function','Sort student scores with a custom key.','Create a sorting key for study durations.',False),
('List comprehensions','comprehension|A compact expression for constructing a new collection.;predicate|An expression that selects members.', 'A comprehension combines iteration, optional filtering and output expression.|It constructs a fresh list.|Prefer an explicit loop if readability suffers.', 'squares = [x*x for x in range(4)]\nprint(squares)','[0, 1, 4, 9]','range(4) yields 0,1,2,3 and each is squared.','Transform collection','Convert raw marks to percentages.','Prepare completed-session summaries.',False),
('Exception handling','exception|A runtime event that interrupts ordinary control flow.;try/except|Construct for controlled error recovery.', 'Place failure-prone operations in try.|Catch only expected exception types.|finally executes cleanup when provided.', 'try:\n    result = 10 / 0\nexcept ZeroDivisionError:\n    print("Cannot divide by zero")','Cannot divide by zero','The expected division error is handled.','Controlled failure','Validate a user-entered duration.','Keep malformed session input from crashing the app.',False),
('*args and **kwargs','args|Variadic positional arguments as a tuple.;kwargs|Variadic named arguments as a dictionary.', '*args collects extra positional values.|**kwargs collects extra named values.|Use them when the calling interface genuinely varies.', 'def total(*scores):\n    return sum(scores)\nprint(total(4, 5))','9','scores is a tuple of supplied positional values.','Flexible signatures','Calculate a total from an unknown number of scores.','Create a flexible session-report formatter.',False),
('Classes','class|A blueprint defining object behavior.;instance|One object created from a class.;method|A function associated with a class.', 'A class defines fields and methods.|__init__ initializes instance state.|Keep each object’s mutable state independent.', 'class Student:\n    def __init__(self, name):\n        self.name = name\nstudent = Student("Derrick")\nprint(student.name)','Derrick','student holds one Student instance with a name attribute.','Object instances','Implement Student and Session classes.','Model a StudySession object.',False),
('Modules','module|A Python file that can be imported.;import|Statement making a module available.', 'Organize related functions into separate .py files.|import loads a module once per interpreter instance in ordinary use.|Avoid circular dependencies and overshadowing standard modules.', 'import math\nprint(math.sqrt(16))','4.0','math.sqrt provides a standard-library function.','Reusable library','Split utilities and CLI code into modules.','Separate models.py and reports.py.',False),
('map()','map|A lazy iterator applying a callable to values.;iterator|An object yielding values on demand.', 'map(function, iterable) transforms each element.|Consume with list() if a concrete list is needed.|A comprehension may be easier to read.', 'values = list(map(int, ["2", "3"]))\nprint(values)','[2, 3]','Each numeric string becomes an integer.','Transform each value','Convert text-form quiz scores to integers.','Normalize imported numeric session data.',False),
('filter()','filter|A lazy iterator retaining elements satisfying a predicate.;predicate|A Boolean-valued condition.', 'filter(function, iterable) keeps truthy results.|Values are not mutated.|A list comprehension may be more readable.', 'values = list(filter(lambda x: x > 2, [1, 3, 4]))\nprint(values)','[3, 4]','Only elements greater than two survive.','Select subset','Select overdue study tasks.','Filter incomplete session records.',False),
('zip()','zip|A lazy iterator pairing corresponding elements of iterables.;pair|Two values grouped at one position.', 'zip matches the first values, then second values, etc.|By default, pairing ends at the shortest iterable.|zip(..., strict=True) rejects unequal lengths.', 'for name, score in zip(["A", "B"], [7, 8]):\n    print(name, score)','A 7\nB 8','Names are paired with scores by position.','Parallel sequences','Pair students with grades.','Merge topic names and durations into records.',False),
('File handling','file handle|A resource used for file I/O.;context manager|A construct that handles resource setup and cleanup.', 'Use with open(...) to close files reliably.|Different modes control reading, writing and appending.|Never overwrite valuable data without making a backup.', 'with open("notes.txt", "w", encoding="utf-8") as file:\n    file.write("Python")\nprint("Saved")','Saved','The context manager closes notes.txt at block exit.','Persistent data','Save a study-session text report.','Persist and restore sessions from JSON.',False),
('Virtual environments','venv|An isolated Python installation context.;dependency|A package required by a project.', 'Create an environment with python3 -m venv .venv.|Activate with source .venv/bin/activate on Ubuntu.|Keep .venv out of Git, and record dependencies in requirements.txt.', 'python3 -m venv .venv\nsource .venv/bin/activate\npython --version','Displays the active Python version','The venv isolates project-installed dependencies.','Reproducible setup','Create a separate environment for Study Intelligence.','Document installation and dependency pinning.',False),
]
lessons=[]
for i,row in enumerate(R,1):
 title,terms,explain,source,expected,reason,diagram,mini,main,supported=row
 defs=[]
 for pair in terms.split(';'):
  key,value=pair.split('|',1); defs.append({'term':key,'meaning':value})
 main_term=defs[0]['term']
 # Distinct, topic-specific assessment with source-grounded correct answer, a not-true distractor and a reliable concept contrast.
 q={'question':f'What does this {title} example demonstrate?', 'options':[reason, f'Python automatically stores this result in a SQL database.',f'The result proves that all Python values are mutable.',f'This program runs JavaScript instead of Python.'], 'answer':0,'explanation':reason}
 repair={'source':f'# Find the correct rule for {title}', 'options':[f'Follow this rule: {reason}', 'Assume a Python variable can only store one type forever.', 'Ignore control flow, object type, and any errors.', 'Treat every Python operation as an SQL query.'], 'answer':0,'explanation':reason}
 obj=[f'Explain {main_term} accurately in your own words.',f'Predict the example output for {title} without running it.',f'Implement and test a small {title.lower()} exercise.']
 lessons.append({'id':f'py-{i:02d}', 'number':i, 'world':'python','title':title,'minutes':25,'objectives':obj,'definitions':defs,
 'explanation':explain.split('|'), 'diagram':diagram, 'source':source,'expected':expected,
 'applications':[f'Engineering: {mini}', f'Study Intelligence: {main}'],
 'quiz':q,'repair':repair,'build':f'Write a new Python example demonstrating {title}. Predict its output, then run it locally with python3 and explain the result.',
 'miniProject':mini,'mainProject':main,'supportedInTracer':supported})
path=pathlib.Path('/mnt/data/codeverse/src/lessons/pythonLessons.json');path.write_text(json.dumps(lessons,ensure_ascii=False,indent=2))
